def squash(s: str) -> str:
    result = []
    i = 0
    n = len(s)

    while i < n:
        c = s[i]
        j = i + 1
        while j < n and s[j] == c:
            j += 1

        escaped = "\\" + c if c == "\\" or "0" <= c <= "9" else c
        length = j - i
        if length >= 3:
            result.append(str(length) + escaped)
        else:
            result.append(escaped * length)

        i = j

    return "".join(result)
